[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --primary: #02838D;
      --primary-dark: #026a75;
      --primary-light: #e6f4f5;
      --charcoal: #231F20;
      --white: #FFFFFF;
      --gray-50: #f8fafb;
      --gray-100: #f1f5f5;
      --gray-200: #e2e8e8;
      --gray-300: #c5d0d0;
      --gray-400: #8a9a9a;
      --gray-500: #5c6f6f;
      --gray-600: #3d4a4a;
      --coral: #e07860;
      --amber: #d4940f;
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --shadow-sm: 0 1px 3px rgba(35,31,32,0.08);
      --shadow-md: 0 4px 12px rgba(35,31,32,0.1);
      --shadow-lg: 0 8px 24px rgba(35,31,32,0.12);
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--gray-50);
      color: var(--charcoal);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { text-decoration: none; color: inherit; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    input { font-family: inherit; border: none; outline: none; }

    /* Header */
    .header {
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      position: sticky;
      top: 0;
      z-index: 1000;
    }

    .header-main {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      font-size: 26px;
      font-weight: 800;
      color: var(--primary);
      letter-spacing: -0.5px;
    }

    .logo span { color: var(--charcoal); }

    .main-nav {
      display: flex;
      gap: 4px;
    }

    .nav-item {
      position: relative;
    }

    .nav-link {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 24px 16px;
      font-size: 15px;
      font-weight: 500;
      color: var(--charcoal);
      transition: color 0.2s;
    }

    .nav-link:hover { color: var(--primary); }
    .nav-link svg { width: 12px; height: 12px; opacity: 0.6; }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-subscribe {
      background: var(--primary);
      color: var(--white);
      padding: 10px 20px;
      border-radius: var(--radius-sm);
      font-size: 14px;
      font-weight: 600;
      transition: background 0.2s;
    }

    .btn-subscribe:hover { background: var(--primary-dark); }

    .btn-signin {
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-600);
      transition: color 0.2s;
    }

    .btn-signin:hover { color: var(--charcoal); }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      padding: 32px;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.25s, visibility 0.25s;
      min-width: 600px;
      border: 1px solid var(--gray-200);
    }

    .nav-item:hover .mega-menu {
      opacity: 1;
      visibility: visible;
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .mega-menu-section h4 {
      font-size: 13px;
      font-weight: 700;
      color: var(--primary);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 12px;
    }

    .mega-menu-section ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .mega-menu-section a {
      font-size: 14px;
      color: var(--gray-600);
      transition: color 0.2s;
      display: block;
      padding: 4px 0;
    }

    .mega-menu-section a:hover { color: var(--primary); }

    /* Credibility Bar */
    .credibility-bar {
      background: linear-gradient(135deg, var(--primary) 0%, #0396a0 100%);
      padding: 12px 0;
      overflow: hidden;
    }

    .ticker-wrapper {
      display: flex;
      animation: ticker 30s linear infinite;
    }

    .ticker-content {
      display: flex;
      gap: 48px;
      padding-right: 48px;
    }

    .ticker-item {
      display: flex;
      align-items: center;
      gap: 10px;
      color: var(--white);
      font-size: 14px;
      font-weight: 500;
      white-space: nowrap;
    }

    .ticker-item .dot {
      width: 8px;
      height: 8px;
      background: rgba(255,255,255,0.4);
      border-radius: 50%;
    }

    @keyframes ticker {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    /* Hero Section */
    .hero {
      max-width: 1280px;
      margin: 0 auto;
      padding: 48px 24px;
      display: grid;
      grid-template-columns: 1fr 340px;
      gap: 48px;
      align-items: center;
    }

    .hero-content { max-width: 600px; }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--primary-light);
      color: var(--primary);
      padding: 6px 14px;
      border-radius: 20px;
      font-size: 13px;
      font-weight: 600;
      margin-bottom: 20px;
    }

    .hero-title {
      font-size: 42px;
      font-weight: 800;
      line-height: 1.15;
      color: var(--charcoal);
      margin-bottom: 16px;
      letter-spacing: -0.5px;
    }

    .hero-subtitle {
      font-size: 18px;
      color: var(--gray-500);
      line-height: 1.6;
      margin-bottom: 28px;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--coral);
      color: var(--white);
      padding: 14px 28px;
      border-radius: var(--radius-md);
      font-size: 15px;
      font-weight: 600;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .hero-cta:hover {
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(224,120,96,0.3);
    }

    .hero-image {
      background: linear-gradient(145deg, var(--primary-light) 0%, #d4e8e9 100%);
      border-radius: var(--radius-lg);
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .hero-image::before {
      content: '';
      position: absolute;
      width: 200px;
      height: 200px;
      background: var(--primary);
      opacity: 0.1;
      border-radius: 50%;
      top: 20%;
      right: 10%;
    }

    .hero-image-icon {
      width: 120px;
      height: 120px;
      background: var(--white);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
    }

    /* Trending Section */
    .trending {
      background: var(--white);
      border-top: 1px solid var(--gray-200);
      border-bottom: 1px solid var(--gray-200);
      padding: 32px 0;
    }

    .trending-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      display: grid;
      grid-template-columns: 1fr 340px;
      gap: 48px;
    }

    .trending-label {
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--coral);
      margin-bottom: 20px;
    }

    .trending-articles {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .trending-article {
      display: flex;
      align-items: flex-start;
      gap: 16px;
      padding: 16px;
      border-radius: var(--radius-md);
      transition: background 0.2s;
    }

    .trending-article:hover { background: var(--gray-50); }

    .trending-article img {
      width: 80px;
      height: 80px;
      border-radius: var(--radius-sm);
      object-fit: cover;
      background: var(--gray-100);
    }

    .trending-article-content { flex: 1; }

    .trending-tag {
      font-size: 11px;
      font-weight: 600;
      color: var(--primary);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 4px;
    }

    .trending-article-title {
      font-size: 15px;
      font-weight: 600;
      color: var(--charcoal);
      line-height: 1.4;
      transition: color 0.2s;
    }

    .trending-article:hover .trending-article-title { color: var(--primary); }

    .popular-topics {
      background: var(--gray-50);
      border-radius: var(--radius-md);
      padding: 24px;
    }

    .popular-topics h3 {
      font-size: 14px;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 16px;
    }

    .topic-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
    }

    .topic-tag {
      background: var(--white);
      border: 1px solid var(--gray-200);
      padding: 8px 14px;
      border-radius: 20px;
      font-size: 13px;
      color: var(--gray-600);
      transition: all 0.2s;
    }

    .topic-tag:hover {
      border-color: var(--primary);
      color: var(--primary);
    }

    /* Newsletter CTA */
    .newsletter-cta {
      background: linear-gradient(135deg, var(--primary) 0%, #0396a0 100%);
      padding: 64px 24px;
      text-align: center;
    }

    .newsletter-cta-inner {
      max-width: 560px;
      margin: 0 auto;
    }

    .newsletter-cta h2 {
      font-size: 32px;
      font-weight: 800;
      color: var(--white);
      margin-bottom: 12px;
    }

    .newsletter-cta p {
      font-size: 16px;
      color: rgba(255,255,255,0.85);
      margin-bottom: 28px;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 460px;
      margin: 0 auto 16px;
    }

    .newsletter-form input {
      flex: 1;
      padding: 14px 20px;
      border-radius: var(--radius-md);
      font-size: 15px;
      background: var(--white);
    }

    .newsletter-form button {
      background: var(--charcoal);
      color: var(--white);
      padding: 14px 28px;
      border-radius: var(--radius-md);
      font-size: 15px;
      font-weight: 600;
      transition: background 0.2s;
    }

    .newsletter-form button:hover { background: #1a1718; }

    .newsletter-privacy {
      font-size: 13px;
      color: rgba(255,255,255,0.7);
    }

    /* Section Common */
    .section {
      max-width: 1280px;
      margin: 0 auto;
      padding: 56px 24px;
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 32px;
    }

    .section-title {
      font-size: 28px;
      font-weight: 800;
      color: var(--charcoal);
    }

    .section-link {
      font-size: 14px;
      font-weight: 600;
      color: var(--primary);
      display: flex;
      align-items: center;
      gap: 6px;
      transition: gap 0.2s;
    }

    .section-link:hover { gap: 10px; }

    /* Health Topics Carousel */
    .health-topics {
      background: var(--white);
      border-top: 1px solid var(--gray-200);
      border-bottom: 1px solid var(--gray-200);
      padding: 56px 0;
    }

    .topics-carousel-wrapper {
      position: relative;
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .topics-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-behavior: smooth;
      padding: 8px 0 16px;
      -ms-overflow-style: none;
      scrollbar-width: none;
    }

    .topics-carousel::-webkit-scrollbar { display: none; }

    .topic-card {
      flex: 0 0 180px;
      text-align: center;
      text-decoration: none;
      transition: transform 0.3s;
    }

    .topic-card:hover { transform: translateY(-4px); }

    .topic-icon {
      width: 100px;
      height: 100px;
      border-radius: 50%;
      background: linear-gradient(145deg, var(--primary-light), #d4e8e9);
      margin: 0 auto 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 36px;
    }

    .topic-card h3 {
      font-size: 15px;
      font-weight: 600;
      color: var(--charcoal);
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 44px;
      height: 44px;
      background: var(--white);
      border-radius: 50%;
      box-shadow: var(--shadow-md);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: box-shadow 0.2s;
      z-index: 10;
    }

    .carousel-btn:hover { box-shadow: var(--shadow-lg); }
    .carousel-btn.prev { left: 0; }
    .carousel-btn.next { right: 0; }

    /* Tools Section */
    .tools-grid {
      display: grid;
      grid-template-columns: 1.2fr 1fr;
      gap: 32px;
    }

    .tools-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid var(--gray-200);
    }

    .tools-card h3 {
      font-size: 20px;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 8px;
    }

    .tools-card > p {
      font-size: 15px;
      color: var(--gray-500);
      margin-bottom: 24px;
    }

    .tools-list {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .tool-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px;
      background: var(--gray-50);
      border-radius: var(--radius-md);
      transition: background 0.2s;
    }

    .tool-item:hover { background: var(--primary-light); }

    .tool-item-info { flex: 1; }

    .tool-item h4 {
      font-size: 14px;
      font-weight: 600;
      color: var(--charcoal);
      margin-bottom: 2px;
    }

    .tool-item p {
      font-size: 13px;
      color: var(--gray-400);
    }

    .tool-arrow {
      width: 32px;
      height: 32px;
      background: var(--white);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      transition: all 0.2s;
    }

    .tool-item:hover .tool-arrow {
      background: var(--primary);
      color: var(--white);
    }

    /* Recommended Reads */
    .recommended-reads {
      background: var(--white);
      border-top: 1px solid var(--gray-200);
    }

    .tabs {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
      margin-bottom: 32px;
    }

    .tab {
      padding: 10px 18px;
      border-radius: 20px;
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-600);
      background: var(--gray-100);
      transition: all 0.2s;
      cursor: pointer;
    }

    .tab:hover { color: var(--primary); }

    .tab.active {
      background: var(--primary);
      color: var(--white);
    }

    .articles-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .article-card {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .article-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .article-image {
      aspect-ratio: 16/10;
      background: linear-gradient(145deg, var(--gray-200), var(--gray-100));
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      font-size: 14px;
    }

    .article-content { padding: 20px; }

    .article-tag {
      font-size: 11px;
      font-weight: 700;
      color: var(--primary);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 8px;
    }

    .article-title {
      font-size: 16px;
      font-weight: 600;
      color: var(--charcoal);
      line-height: 1.4;
      margin-bottom: 12px;
    }

    .article-meta {
      font-size: 12px;
      color: var(--gray-400);
    }

    /* Trust Section */
    .trust-section {
      background: var(--gray-50);
      border-top: 1px solid var(--gray-200);
      padding: 80px 0;
      text-align: center;
    }

    .trust-inner { max-width: 1280px; margin: 0 auto; padding: 0 24px; }

    .trust-section .section-title {
      font-size: 36px;
      margin-bottom: 48px;
    }

    .trust-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      text-align: center;
    }

    .trust-card {
      padding: 32px 24px;
    }

    .trust-icon {
      width: 64px;
      height: 64px;
      background: var(--white);
      border-radius: 50%;
      margin: 0 auto 20px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 28px;
      box-shadow: var(--shadow-sm);
    }

    .trust-card h4 {
      font-size: 18px;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 10px;
    }

    .trust-card p {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* Featured Programs */
    .featured-programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .program-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .program-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .program-image {
      aspect-ratio: 16/9;
      background: linear-gradient(145deg, var(--primary-light), #d4e8e9);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--primary);
      font-size: 14px;
      font-weight: 500;
    }

    .program-content { padding: 20px; }

    .program-content h3 {
      font-size: 16px;
      font-weight: 600;
      color: var(--charcoal);
    }

    /* Latest Videos */
    .latest-videos {
      background: var(--charcoal);
    }

    .latest-videos .section-title { color: var(--white); }
    .latest-videos .section-link { color: rgba(255,255,255,0.7); }
    .latest-videos .section-link:hover { color: var(--white); }

    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .video-card {
      position: relative;
      border-radius: var(--radius-md);
      overflow: hidden;
    }

    .video-thumbnail {
      aspect-ratio: 16/9;
      background: linear-gradient(145deg, var(--gray-600), var(--gray-500));
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .play-btn {
      width: 56px;
      height: 56px;
      background: rgba(255,255,255,0.95);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
    }

    .play-btn::after {
      content: '';
      width: 0;
      height: 0;
      border-left: 16px solid var(--primary);
      border-top: 10px solid transparent;
      border-bottom: 10px solid transparent;
      margin-left: 4px;
    }

    .video-info {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      padding: 16px;
      background: linear-gradient(transparent, rgba(0,0,0,0.8));
    }

    .video-info h3 {
      font-size: 14px;
      font-weight: 600;
      color: var(--white);
    }

    /* Footer */
    .footer {
      background: var(--white);
      border-top: 1px solid var(--gray-200);
      padding: 64px 0 32px;
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .footer-newsletter {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 40px;
      text-align: center;
      margin-bottom: 48px;
    }

    .footer-newsletter h3 {
      font-size: 22px;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 12px;
    }

    .footer-newsletter p {
      font-size: 15px;
      color: var(--gray-500);
      max-width: 500px;
      margin: 0 auto 24px;
    }

    .footer-form {
      display: flex;
      gap: 12px;
      max-width: 440px;
      margin: 0 auto;
    }

    .footer-form input {
      flex: 1;
      padding: 14px 20px;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-md);
      font-size: 15px;
      background: var(--white);
    }

    .footer-form button {
      background: var(--primary);
      color: var(--white);
      padding: 14px 24px;
      border-radius: var(--radius-md);
      font-size: 15px;
      font-weight: 600;
      transition: background 0.2s;
    }

    .footer-form button:hover { background: var(--primary-dark); }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
